head.script:
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById($p.id+'wframe1_input1').realValue == 'aaaa';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. wframeSwitch.xml 을 브라우저로 실행한다.
    //1. Run wframeSwitch.xml as a browser.
    //Verify 1. wframe 안에 데이터가 바인딩되서 보여진다.
    //1. Data is bound to be displayed in a wframe.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //wframe1.setSrc("/TEST/web5_test/SP2/2016/uiplugin/wframe/wframe_Scope_SKT-283_(WSQ-929)_sub.xml");
	wframe1.setSrc("/TEST_SP5/web5_test/SP2/2016/uiplugin/wframe/wframe_Scope_SKT-283_(WSQ-929)_sub.xml");
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 01-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
